{
  "translations": {
    "L0001": "Je n’ai pas dit d’appuyer sur le bouton rouge.",
    "L0002": "Le mode d’emploi était dans le tiroir.",
    "L0003": "La lumière s’est allumée un instant, puis s’est éteinte.",
    "L0004": "J’ai dit de ne pas appuyer sur le bouton rouge.",
    "L0005": "Toi aussi, tu as entendu que les mots avaient changé.",
    "L0006": "Je ne sais toujours pas qui a appuyé."
  },
  "sourceNotes": []
}
